import re#类型名整词


__all__=['服务api','事件api','类型api','继承上下文api','引用类型闭包']


def 方法(签名,说明,参数=None,返回=None,抛出=None):
    '一条服务方法。字段名保持上游'
    项={'signature':签名,'description':说明,'parameters':[] if 参数 is None else 参数}#方法
    if 返回 is not None:#有返回说明
        项['returns']=返回#返回
    if 抛出 is not None:#有失败说明
        项['throws']=抛出#失败
    return 项


def 参(名,说明):
    '一条参数'
    return {'name':名,'description':说明}


