        方法('retain(target: SessionTarget, options: SessionRetainOptions): SessionReference','Retain an exact Client generation and start its shared initial history opening.',[参('target','known identity or durable direct-parent address.'),参('options','required consumer source and optional independent waiter cancellation.')],"an owned reference immediately; await `reference.ready` when the initial open attempt must settle first."),
        方法('using<T>(target: SessionTarget, options: SessionRetainOptions, operation: (reference: SessionReference) => T | Promise<T>): Promise<T>','Hold one reference through callback settlement, including synchronous and asynchronous failures.',[参('target','Session to acquire.'),参('options','source and acquisition cancellation.'),参('operation','callback using the reference only until its returned value or Promise settles.')],'the callback result after release; acquisition and callback failures propagate unchanged.'),
        方法('retainInfo(id: SessionId): ObservableSnapshot<SessionRetainInfo>','Observe local reference counts without retaining, creating a scope, or opening history. The returned source keeps stable identity across same-id generations and remains allocated until the Client root is disposed, even after its final subscriber leaves.',[参('id','explicit Session identity; Host existence is not implied.')],'a stable read-only source across same-id generations, with zero counts when none is live.'),
        方法('refreshProjections(sessionId: SessionId): Promise<void>','Read projections without starting migration; retry failed or migration-deferred reads.',[参('sessionId','Session to inspect without opening its conversation.')],'completion of the current or newly started refresh.'),
